// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        address owner = address(c.owner());
        vm.deal(owner, 0);
        vm.deal(address(c), amount - 1);
        vm.prank(owner);
        bool ok = true;
        try c.withdraw(amount) { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}
